void indent(std::ostream& output, int depth) {
    for (int index = 0; index < depth; ++index) {
        output << "  ";
    }
}

const char* expressionName(ExpressionKind kind) {
    switch (kind) {
    case ExpressionKind::BoundMethod: return "BoundMethod";
    case ExpressionKind::CallbackCall: return "CallbackCall";
    case ExpressionKind::Integer: return "Integer";
    case ExpressionKind::Unsigned: return "Unsigned";
    case ExpressionKind::Float: return "Float";
    case ExpressionKind::Boolean: return "Boolean";
    case ExpressionKind::String: return "String";
    case ExpressionKind::FormatString: return "FormatString";
    case ExpressionKind::Identifier: return "Identifier";
    case ExpressionKind::ImplicitThis: return "ImplicitThis";
    case ExpressionKind::Unary: return "Unary";
    case ExpressionKind::Binary: return "Binary";
    case ExpressionKind::Member: return "Member";
    case ExpressionKind::EnumConstant: return "EnumConstant";
    case ExpressionKind::Call: return "Call";
    case ExpressionKind::ConstructorCall: return "ConstructorCall";
    case ExpressionKind::BufferConstructor: return "BufferConstructor";
    case ExpressionKind::BufferLiteral: return "BufferLiteral";
    case ExpressionKind::Null: return "Null";
    case ExpressionKind::ArrayLiteral: return "ArrayLiteral";
    case ExpressionKind::MapLiteral: return "MapLiteral";
    case ExpressionKind::Index: return "Index";
    case ExpressionKind::Slice: return "Slice";
    case ExpressionKind::Cast: return "Cast";
    case ExpressionKind::ObjectCast: return "ObjectCast";
    case ExpressionKind::TypeTest: return "TypeTest";
    case ExpressionKind::TypeOf: return "TypeOf";
    case ExpressionKind::TypeName: return "TypeName";
    }
    return "Expression";
}

void dumpExpression(const Expression& expression, std::ostream& output, int depth) {
    indent(output, depth);
    output << expressionName(expression.kind);
    if (!expression.value.empty()) {
        output << " [" << expression.value << "]";
    }
    output << '\n';
    if (expression.left) {
        dumpExpression(*expression.left, output, depth + 1);
    }
    if (expression.right) {
        dumpExpression(*expression.right, output, depth + 1);
    }
    for (const auto& argument : expression.arguments) {
        dumpExpression(*argument, output, depth + 1);
    }
}

void dumpStatements(const std::vector<Statement>& statements, std::ostream& output, int depth);

void dumpStatement(const Statement& statement, std::ostream& output, int depth) {
    indent(output, depth);
    switch (statement.kind) {
    case StatementKind::Declaration:
        output << "Declaration [" << statement.declaredType << " " << statement.name << "]\n";
        break;
    case StatementKind::Assignment:
        output << "Assignment";
        if (statement.assignmentOperator != "=") {
            output << " [" << statement.assignmentOperator << "]";
        }
        output << '\n';
        break;
    case StatementKind::Print: output << "Print\n"; break;
    case StatementKind::If: output << "If\n"; break;
    case StatementKind::While: output << "While\n"; break;
    case StatementKind::DoWhile: output << "Do while\n"; break;
    case StatementKind::Break: output << "Break\n"; break;
    case StatementKind::Continue: output << "Continue\n"; break;
    case StatementKind::ForEach:
        output << (statement.keyName.empty()
                       ? "For each [" + statement.name + "]\n"
                       : "For each [" + statement.keyName + ", " + statement.name + "]\n");
        break;
    case StatementKind::Block: output << "Block\n"; break;
    case StatementKind::Return: output << "Return\n"; break;
    case StatementKind::Expression: output << "Expression statement\n"; break;
    case StatementKind::SuperConstructorCall:
        output << (statement.virtualBaseInitializer ? "Super virtual constructor [" :
                                                       "Super constructor [")
               << statement.name << "]\n";
        break;
    case StatementKind::Raise: output << "Raise\n"; break;
    case StatementKind::Try: output << "Try\n"; break;
    case StatementKind::InlineC: output << "Inline C\n"; break;
    }
    if (statement.target) {
        dumpExpression(*statement.target, output, depth + 1);
    }
    for (const auto& expression : statement.expressions) {
        dumpExpression(*expression, output, depth + 1);
    }
    if (!statement.body.empty()) {
        dumpStatements(statement.body, output, depth + 1);
    }
    if (statement.kind == StatementKind::Try) {
        for (const auto& handler : statement.exceptionHandlers) {
            indent(output, depth + 1);
            output << "Except";
            if (!handler.exceptionType.empty()) {
                output << " [" << handler.exceptionType << "]";
            }
            if (handler.hasBinding) output << " as [" << handler.name << "]";
            output << '\n';
            dumpStatements(handler.body, output, depth + 2);
        }
    } else if (statement.hasAlternate) {
        indent(output, depth + 1);
        output << "Else\n";
        dumpStatements(statement.alternate, output, depth + 2);
    }
    if (statement.hasCleanup) {
        indent(output, depth + 1);
        output << "Finally\n";
        dumpStatements(statement.cleanup, output, depth + 2);
    }
}

void dumpStatements(const std::vector<Statement>& statements, std::ostream& output, int depth) {
    for (const auto& statement : statements) {
        dumpStatement(statement, output, depth);
    }
}

