void dumpAst(const Program& program, std::ostream& output) {
    output << "Program\n";
    for (const auto& import : program.imports) {
        indent(output, 1);
        output << "Import [" << import.moduleName;
        if (!import.alias.empty()) output << " as " << import.alias;
        output << "]\n";
    }
    for (const auto& declaration : program.namespaces) {
        indent(output, 1);
        output << "Namespace [";
        for (std::size_t index = 0; index < declaration.path.size(); ++index) {
            if (index != 0) output << ".";
            output << declaration.path[index];
        }
        output << "]\n";
    }
    for (const auto& definition : program.outOfLineMethods) {
        indent(output, 1);
        output << "Out-of-line method [" << definition.className << "."
               << definition.method.returnType << " " << definition.method.name << "(";
        for (std::size_t index = 0; index < definition.method.parameters.size(); ++index) {
            if (index != 0) output << ", ";
            output << definition.method.parameters[index].type << " "
                   << definition.method.parameters[index].name;
        }
        output << ")";
        if (definition.method.externalBinding) {
            output << " from \"" << definition.method.externalSymbol << "\"";
        }
        output << "]\n";
    }
    for (const auto& declaration : program.classes) {
        if (declaration.builtin) continue;
        indent(output, 1);
        output << "Class [" << declaration.name;
        if (!declaration.baseClassNames.empty()) {
            output << " : ";
            for (std::size_t index = 0; index < declaration.baseClassNames.size(); ++index) {
                if (index != 0) output << ", ";
                const char* access = declaration.baseAccess[index] == AccessLevel::Public
                                         ? "public "
                                         : declaration.baseAccess[index] == AccessLevel::Protected
                                               ? "protected "
                                               : "private ";
                output << access;
                if (declaration.baseVirtual[index]) output << "virtual ";
                output << declaration.baseClassNames[index];
            }
        }
        output << "]\n";
        for (const auto& field : declaration.fields) {
            indent(output, 2);
            output << "Field [" << field.type << " " << field.name << "]\n";
        }
        for (const auto& member : declaration.enumMembers) {
            indent(output, 2);
            output << "Enum member [" << member.name;
            if (member.value) output << " = " << *member.value;
            output << "]\n";
        }
        for (const auto& method : declaration.methods) {
            indent(output, 2);
            output << (method.constructor ? "Constructor [" :
                       method.declarationOnly ? "Method declaration [" : "Method [")
                   << method.returnType << " " << method.name << "]\n";
            dumpStatements(method.body, output, 3);
        }
    }
    dumpStatements(program.statements, output, 1);
}

